            aOrbiterF = (aOrbiterF + aOrbiterI) + 0x6B4FDEEF3E11A5A0ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterF) ^ 0x49321F76DD4EA140ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x6AEEDC52EA132C19ULL), 57U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterF) + 0x260645C4AEDDA555ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterC) ^ 0x2AFE8DC18DCA8C9BULL) ^ aTwistOrbiterUpdateSaltA[((aIndex + 11U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x59D301AD90E69CF1ULL), 41U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterD) + 0xF1FD435C15CED302ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterH) ^ 0xAA9C2A84A878CE4FULL;
