            //
            aWandererB = aWandererB ^ (((RotL64(aCross, 5U) + RotL64(aOrbiterJ, 3U)) + aOrbiterA) + aTwistWandererUpdateSaltF[(((31U - aIndex) + 26U)) & S_SALT1]);
            aWandererK = aWandererK + (((RotL64(aScatter, 51U) + aOrbiterI) + RotL64(aOrbiterF, 10U)) + RotL64(aCarry, 19U));
            aWandererE = aWandererE ^ ((RotL64(aPrevious, 13U) + RotL64(aOrbiterH, 47U)) + aOrbiterI);
            aWandererA = aWandererA + (((RotL64(aIngress, 39U) + aOrbiterI) + RotL64(aOrbiterD, 29U)) + RotL64(aCarry, 39U));
            aWandererF = aWandererF ^ (((RotL64(aPrevious, 58U) + RotL64(aOrbiterC, 21U)) + aOrbiterI) + aTwistWandererUpdateSaltE[(((31U - aIndex) + 14U)) & S_SALT1]);
