            aOrbiterG = ((aWandererC + RotL64(aPrevious, 11U)) + 0x5070C5DC0B83B870ULL) + aTwistOrbiterAssignSaltC[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterA = ((aWandererH + RotL64(aIngress, 41U)) + 0x75BE94B2D4B61C7CULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterF = (aWandererG + RotL64(aScatter, 20U)) + 0x1AC2B772E6C0E4A6ULL;
            aOrbiterD = ((aWandererI + RotL64(aIngress, 47U)) + RotL64(aCarry, 5U)) + 0xCF14C61B0CDC7297ULL;
            aOrbiterI = ((aWandererA + RotL64(aPrevious, 53U)) + RotL64(aCarry, 43U)) + 0xD4BF0D2E8AF9482BULL;
            aOrbiterC = (aWandererE + RotL64(aScatter, 5U)) + 0xFC08BC876EB4BBDAULL;
