            aOrbiterB = (aOrbiterB + aOrbiterG) + 0xAC93C146CED5EFDDULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterB) ^ 0x99973654DE09A5C9ULL) ^ aTwistOrbiterUpdateSaltF[((aIndex + 8U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0xE87E19E99EEFC459ULL), 53U);
