            //
            aIngress = (RotL64(aFuseLaneA[((aIndex + 10592U)) & S_BLOCK1], 24U) ^ RotL64(aWaterLaneC[((aIndex + 8733U)) & S_BLOCK1], 37U));
            aIngress ^= (RotL64(aFireLaneB[((aIndex + 14304U)) & S_BLOCK1], 13U) ^ RotL64(pSnowLaneA[((aIndex + 13837U)) & S_BLOCK1], 57U));
