            aCross ^= (RotL64(aFireLaneA[((S_BLOCK1 - aIndex + 12885U)) & S_BLOCK1], 3U) ^ RotL64(aEarthLaneB[((S_BLOCK1 - aIndex + 10391U)) & S_BLOCK1], 52U));
