            aScatter = (RotL64(aPrevious, 11U) ^ RotL64(aCross, 39U)) + (RotL64(aIngress, 23U) + RotL64(aCarry, 58U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterE = (aWandererF + RotL64(aIngress, 23U)) + 0x3A28AF4B383082C5ULL;
            aOrbiterF = (aWandererK + RotL64(aCross, 43U)) + 0xAF53CBD7A48E1BCCULL;
            aOrbiterJ = ((aWandererE + RotL64(aPrevious, 5U)) + RotL64(aCarry, 53U)) + 0x9B6CD7A6E06A43A1ULL;
            aOrbiterC = (aWandererA + RotL64(aScatter, 53U)) + 0x03F585110988F0D9ULL;
            aOrbiterG = ((aWandererB + RotL64(aPrevious, 37U)) + 0x0B66810C8471D409ULL) + aTwistOrbiterAssignSaltA[((aIndex + 13U)) & S_SALT1];
            aOrbiterB = ((aWandererH + RotL64(aScatter, 14U)) + RotL64(aCarry, 37U)) + 0x233C54D609B2B888ULL;
            aOrbiterH = (((aWandererJ + RotL64(aIngress, 29U)) + RotL64(aCarry, 5U)) + 0x145B44059089B57EULL) + aTwistOrbiterAssignSaltB[(((31U - aIndex) + 24U)) & S_SALT1];
            //
            aOrbiterE = (aOrbiterE + aOrbiterF) + 0xB15648FD21B739CDULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterE) ^ 0x8D2D33F69D2BCC44ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x85F158464BA2F393ULL), 23U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterC) + 0x4FABFA144C88BC2CULL) + aTwistOrbiterUpdateSaltD[((aIndex + 3U)) & S_SALT1];
            aOrbiterG = ((aOrbiterG ^ aOrbiterJ) ^ 0x63277DE770162373ULL) ^ aTwistOrbiterUpdateSaltF[((aIndex + 4U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x9D2BD0DBA67A748FULL), 57U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterJ) + 0x7357F1759E9123E5ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0x6A65A7432D15A67DULL;
            aOrbiterH = RotL64((aOrbiterH * 0xAF3B675E31018819ULL), 13U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterG) + 0x7048AB3245842AF2ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterH) ^ 0xE9D0D0E7AE05ED82ULL) ^ aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0xD97AE26B3F39A311ULL), 47U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterB) + 0xAA82BB5BAF0EEA8FULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterF) ^ 0x9B4F523E6F2998D9ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x3492F3494361BEA1ULL), 37U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterE) + 0xD0FAFB232C2D8A39ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterG) ^ 0x7D4EF03BB8BD8773ULL) ^ aTwistOrbiterUpdateSaltB[((aIndex + 28U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x1053EEAFAB151AD3ULL), 29U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterH) + 0xEE1A03E6BED5EB3EULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterC) ^ 0x2D9CD47912744A14ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xD35EF3EBCE8A6E8FULL), 5U);
