            aOrbiterK = (aOrbiterK + aOrbiterI) + 0xEAC67DCEDD9057E2ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterK) ^ 0x9B355578332FE951ULL) ^ aTwistOrbiterUpdateSaltE[((aIndex + 12U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0xC3EB28633D5159E7ULL), 41U);
