            aOrbiterD = ((aWandererJ + RotL64(aPrevious, 34U)) + 0x1BFAFB33E91298C2ULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterJ = (aWandererG + RotL64(aCross, 5U)) + 0xDFD66CD374FE5D76ULL;
            aOrbiterC = ((aWandererC + RotL64(aIngress, 11U)) + RotL64(aCarry, 27U)) + 0xF2E2BC0CA423C060ULL;
