            aOrbiterC = ((aOrbiterC + aOrbiterJ) + 0x5D6EA86D5D02B45DULL) + aTwistOrbiterUpdateSaltD[((aIndex + 25U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterC) ^ 0x41FA22F2A3D9DA74ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x41DF2C41A51206C7ULL), 27U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterA) + 0x229F2E54EA2108DDULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterE) ^ 0xE15A3ED1EDC55ED3ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x1569872509BAD769ULL), 47U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterE) + 0xC2EDF7E0A0A1F3AEULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterB) ^ 0x38D0F912C13210FAULL;
            aOrbiterG = RotL64((aOrbiterG * 0xAC5D0D1C70DFC623ULL), 29U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterH) + 0x0F459386CED10CBBULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterG) ^ 0x08908A4A7481203EULL;
            aOrbiterI = RotL64((aOrbiterI * 0x60A64D50572CFDADULL), 35U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterC) + 0xBEEEFE8EEF621A8CULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterD) ^ 0xAAA59B36DAF38AA1ULL) ^ aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x73E9DE093B6CDF1BULL), 11U);
