            aOrbiterI = (aWandererE + RotL64(aCross, 47U)) + 0x3E64EDB03DDDEC1EULL;
            aOrbiterK = ((aWandererD + RotL64(aIngress, 41U)) + RotL64(aCarry, 21U)) + 0x010FC883840F7937ULL;
            aOrbiterB = (aWandererA + RotL64(aCross, 29U)) + 0x40ECE1E58DE7138BULL;
            aOrbiterF = (((aWandererG + RotL64(aScatter, 6U)) + RotL64(aCarry, 41U)) + 0x368D4C8E11CD6425ULL) + aKeyRotateOrbiterAssignSaltA[(((31U - aIndex) + 24U)) & S_SALT1];
            aOrbiterJ = ((aWandererF + RotL64(aPrevious, 35U)) + 0x5EEEB8CF593766B0ULL) + aKeyRotateOrbiterAssignSaltC[(((31U - aIndex) + 7U)) & S_SALT1];
            //
            aOrbiterD = (aOrbiterD + aOrbiterC) + 0x60E4746560E8E3D8ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterD) ^ 0xE3E52DF49B0AD8E2ULL;
