            //
            aOrbiterB = ((aOrbiterB + aOrbiterF) + 0xDDC626C29335B9D8ULL) + aKeyRotateOrbiterUpdateSaltF[(((31U - aIndex) + 20U)) & S_SALT1];
            aOrbiterD = ((aOrbiterD ^ aOrbiterB) ^ 0x8EDF7479AADC5644ULL) ^ aKeyRotateOrbiterUpdateSaltE[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x0C977293770B6B3DULL), 5U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterD) + 0xD3657D4347BDB51CULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterF) ^ 0xE6466B241FD2527BULL;
            aOrbiterC = RotL64((aOrbiterC * 0x66C598E0290FE3B1ULL), 39U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterJ) + 0xCF879889874643EFULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterK) ^ 0x82B79E7B8CA2C58AULL) ^ aKeyRotateOrbiterUpdateSaltD[((aIndex + 25U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x85C4C4B1D0A4DFDBULL), 57U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterK) + 0x75AEC62ADD485D50ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterI) ^ 0x939A4704E9B698CDULL;
