            //
            aOrbiterJ = (aOrbiterJ + aOrbiterB) + 0x14F6A7785C8EB536ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterJ) ^ 0xEB7676C35A3AB56BULL;
            aOrbiterF = RotL64((aOrbiterF * 0x1E5472F5E54AA829ULL), 47U);
            //
            aIngress = RotL64(aOrbiterC, 41U) ^ aOrbiterF;
            aIngress = aIngress + (RotL64(aOrbiterJ, 11U) ^ aOrbiterK);
