            //
            aWandererE = aWandererE ^ ((RotL64(aPrevious, 4U) + aOrbiterJ) + RotL64(aOrbiterF, 51U));
            aWandererH = aWandererH + ((((RotL64(aIngress, 29U) + RotL64(aOrbiterB, 21U)) + aOrbiterF) + RotL64(aCarry, 27U)) + aKeyRotateWandererUpdateSaltE[((aIndex + 19U)) & S_SALT1]);
