            aWandererD = aWandererD ^ ((RotL64(aCross, 43U) + aOrbiterI) + RotL64(aOrbiterB, 57U));
            aWandererF = aWandererF + (((RotL64(aScatter, 35U) + aOrbiterB) + RotL64(aOrbiterD, 3U)) + RotL64(aCarry, 53U));
            aWandererA = aWandererA ^ (((RotL64(aPrevious, 11U) + RotL64(aOrbiterK, 30U)) + aOrbiterC) + aKeyRotateWandererUpdateSaltB[((aIndex + 23U)) & S_SALT1]);
