            aOrbiterA = (aWandererF + RotL64(aIngress, 3U)) + 0x684FBF05C0F3F140ULL;
            aOrbiterK = ((aWandererI + RotL64(aPrevious, 11U)) + 0x51C613E67A6BAFCFULL) + aKeyRotateOrbiterAssignSaltF[((aIndex + 15U)) & S_SALT1];
            aOrbiterD = ((aWandererC + RotL64(aIngress, 35U)) + RotL64(aCarry, 23U)) + 0xC1699AAEF48B489FULL;
            aOrbiterJ = (aWandererA + RotL64(aScatter, 46U)) + 0x874A94C655E1F389ULL;
