            aOrbiterK = RotL64((aOrbiterK * 0xBE80C7B41174F63DULL), 47U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterK) + 0x22B10579BCA06D3BULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterA) ^ 0x776608498428DC31ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xF8F9186863314D59ULL), 19U);
