            aOrbiterK = ((aOrbiterK + aOrbiterD) + 0xEC1560294B0AE33BULL) + aKeyRotateOrbiterUpdateSaltF[(((31U - aIndex) + 16U)) & S_SALT1];
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterK) ^ 0x4BCE948381B7C85EULL) ^ aKeyRotateOrbiterUpdateSaltB[((aIndex + 22U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x4C373084CB04DB3DULL), 3U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterJ) + 0xE8E8B2A0B11383A8ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterD) ^ 0x1782752B869C4E06ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x7E3D4F2864E91923ULL), 39U);
