            aOrbiterI = (aOrbiterI + aOrbiterC) + 0xD6AEC75B275266A1ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterI) ^ 0x4F75AE7311F635BEULL) ^ aKeyRotateOrbiterUpdateSaltE[((aIndex + 27U)) & S_SALT1];
