            aCross = (RotL64(aWindLaneC[((S_BLOCK1 - aIndex + 5245U)) & S_BLOCK1], 10U) ^ RotL64(aFireLaneB[((S_BLOCK1 - aIndex + 2530U)) & S_BLOCK1], 57U));
            aCross ^= (RotL64(aKeyRowReadB[(((2047U - aIndex) + 3516U)) & W_KEY1], 35U) ^ RotL64(aPoisonLaneB[((S_BLOCK1 - aIndex + 6351U)) & S_BLOCK1], 23U));
            aCross = TwistMix64::DiffuseC(aCross);
            //
            aScatter = (RotL64(aCross, 24U) ^ RotL64(aPrevious, 37U)) + (RotL64(aIngress, 11U) ^ RotL64(aCarry, 53U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterC = (aWandererC + RotL64(aCross, 54U)) + 0x1E689AC07F5B613DULL;
            aOrbiterH = (aWandererD + RotL64(aScatter, 35U)) + 0x277886F2D18AFB10ULL;
            aOrbiterD = (aWandererE + RotL64(aIngress, 19U)) + 0x6C4863A6E5F75672ULL;
            aOrbiterE = ((aWandererB + RotL64(aPrevious, 37U)) + RotL64(aCarry, 47U)) + 0xEDAA43C68708BD8FULL;
            aOrbiterJ = (aWandererK + RotL64(aScatter, 51U)) + 0x2CDF2A2725E38AE4ULL;
            aOrbiterG = (aWandererI + RotL64(aIngress, 4U)) + 0x219F5F5E81BBF738ULL;
            aOrbiterK = ((aWandererH + RotL64(aCross, 39U)) + RotL64(aCarry, 53U)) + 0x3EEA11CD74243C22ULL;
            aOrbiterI = (aWandererA + RotL64(aPrevious, 47U)) + 0x8B1AB89D5C56EB08ULL;
            aOrbiterB = ((aWandererJ + RotL64(aIngress, 23U)) + RotL64(aCarry, 13U)) + 0x9DB39BB4C2DFD020ULL;
            aOrbiterA = ((aWandererG + RotL64(aCross, 57U)) + 0x52BC540B859FCD0BULL) + aKeyRotateOrbiterAssignSaltD[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterF = ((aWandererF + RotL64(aPrevious, 11U)) + 0x7ACC26AD28820DDEULL) + aKeyRotateOrbiterAssignSaltC[((aIndex + 12U)) & S_SALT1];
            //
            aOrbiterC = ((aOrbiterC + aOrbiterH) + 0xE34E5ECF5909E607ULL) + aKeyRotateOrbiterUpdateSaltF[(((31U - aIndex) + 4U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterC) ^ 0x384A0968F67799B3ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xB932DDBA862A9903ULL), 35U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterC) + 0x4279676B50816B8EULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterE) ^ 0xF6B93BFAFA8B1E2BULL) ^ aKeyRotateOrbiterUpdateSaltA[((aIndex + 19U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x5C990A655BF8903FULL), 53U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterK) + 0x0F5898F56A88533FULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterG) ^ 0xE7D86CD69B2261F8ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x07591E27771A2C3BULL), 23U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterB) + 0xA3B372C92AA90A58ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterI) ^ 0xB3ACA0CD684E2DA6ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x9D4F95B9C608A7F5ULL), 13U);
