            aWandererK = aWandererK + ((RotL64(aIngress, 35U) + aOrbiterI) + RotL64(aOrbiterB, 39U));
            aWandererA = aWandererA ^ ((RotL64(aPrevious, 57U) + RotL64(aOrbiterH, 43U)) + aOrbiterF);
            aWandererF = aWandererF + (((RotL64(aScatter, 51U) + aOrbiterD) + RotL64(aOrbiterF, 18U)) + aKeyRotateWandererUpdateSaltE[(((31U - aIndex) + 19U)) & S_SALT1]);
            //
            aCarry = aCarry + (RotL64(aWandererC, 14U) ^ aWandererB);
            aCarry = aCarry + (RotL64(aWandererF, 41U) ^ aWandererH);
