            aIngress ^= (RotL64(aKineticLaneC[((aIndex + 14999U)) & S_BLOCK1], 13U) ^ RotL64(aAetherLaneD[((S_BLOCK1 - aIndex + 13697U)) & S_BLOCK1], 48U));
