            aCross ^= (RotL64(aKeyRowReadB[(((2047U - aIndex) + 11912U)) & W_KEY1], 23U) ^ RotL64(aKineticLaneB[((S_BLOCK1 - aIndex + 10826U)) & S_BLOCK1], 50U));
